import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Typography,
  Box,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";

const ClientDB = () => {
  const [clients, setClients] = useState([
    {
      id: 1,
      companyName: "Tech Solutions Inc.",
      contactPerson: "John Smith",
      mobileNumber: "+1 (555) 123-4567",
      email: "john.smith@techsolutions.com",
      address: "123 Business Ave, Suite 100, New York, NY 10001",
    },
  ]);
  const [open, setOpen] = useState(false);
  const [newClient, setNewClient] = useState({
    companyName: "",
    contactPerson: "",
    mobileNumber: "",
    email: "",
    address: "",
  });
  const navigate = useNavigate();

  useEffect(() => {
    // Fetch clients data from your API
    const fetchClients = async () => {
      try {
        const response = await axios.get("/api/clients"); // Update with your actual API endpoint
        setClients(response.data);
      } catch (error) {
        console.error("Error fetching clients:", error);
      }
    };

    fetchClients();
  }, []);

  const handleRowClick = (clientId) => {
    navigate("/cert-db", { state: { clientId } });
  };

  const handleClickOpen = () => {
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setNewClient({
      companyName: "",
      contactPerson: "",
      mobileNumber: "",
      email: "",
      address: "",
    });
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewClient((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = async () => {
    try {
      // Add API call to save the new client
      // const response = await axios.post("/api/clients", newClient);
      // setClients([...clients, response.data]);

      // For now, just add to local state
      const newClientWithId = {
        ...newClient,
        id: clients.length + 1,
      };
      setClients([...clients, newClientWithId]);
      handleClose();
    } catch (error) {
      console.error("Error adding client:", error);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 3,
        }}
      >
        <Typography variant="h4">Client Database</Typography>
        <Button
          variant="contained"
          color="primary"
          startIcon={<AddIcon />}
          onClick={handleClickOpen}
        >
          Add Client
        </Button>
      </Box>
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Company Name</TableCell>
              <TableCell>Contact Person</TableCell>
              <TableCell>Mobile Number</TableCell>
              <TableCell>Email</TableCell>
              <TableCell>Address</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {clients.map((client) => (
              <TableRow
                key={client.id}
                onClick={() => handleRowClick(client.id)}
                sx={{
                  cursor: "pointer",
                  "&:hover": { backgroundColor: "#f5f5f5" },
                }}
              >
                <TableCell>{client.companyName}</TableCell>
                <TableCell>{client.contactPerson}</TableCell>
                <TableCell>{client.mobileNumber}</TableCell>
                <TableCell>{client.email}</TableCell>
                <TableCell>{client.address}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>Add New Client</DialogTitle>
        <DialogContent>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2, pt: 2 }}>
            <TextField
              label="Company Name"
              name="companyName"
              value={newClient.companyName}
              onChange={handleInputChange}
              fullWidth
              required
            />
            <TextField
              label="Contact Person"
              name="contactPerson"
              value={newClient.contactPerson}
              onChange={handleInputChange}
              fullWidth
              required
            />
            <TextField
              label="Mobile Number"
              name="mobileNumber"
              value={newClient.mobileNumber}
              onChange={handleInputChange}
              fullWidth
              required
            />
            <TextField
              label="Email"
              name="email"
              type="email"
              value={newClient.email}
              onChange={handleInputChange}
              fullWidth
              required
            />
            <TextField
              label="Address"
              name="address"
              value={newClient.address}
              onChange={handleInputChange}
              fullWidth
              required
              multiline
              rows={3}
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancel</Button>
          <Button onClick={handleSubmit} variant="contained" color="primary">
            Add Client
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ClientDB;
